import { describe, it, expect } from "vitest";
import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  it("scores an army without a Sphinx as 0 — Chimera, Orthrus, Zombie → 0", () => {
    expect(
      scoreArmy([
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
      ]),
    ).toBe(0);
  });
  it("scores a Sphinx with one other type as 2 — Sphinx, Cyclops → 2", () => {
    expect(scoreArmy([{ monster: "sphinx" }, { monster: "cyclops" }])).toBe(2);
  });
  it("scores a Sphinx with three types in the army as 2 — Sphinx, Chimera, Orthrus → 2", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
      ]),
    ).toBe(2);
  });
  it("counts repeated cards of the same monster once — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "chimera" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "orthrus" },
      ]),
    ).toBe(2);
  });
  it.todo("pays 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3");
  it.todo("pays 2 for each further type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5");
  it.todo("counts all Undead Warrior variants as one type — Sphinx, Undead Warrior (1), Undead Warrior (3), Chimera → 2");
  it.todo("counts all three Undead Warrior variants as one type beyond three — Sphinx, Undead Warrior (1), Undead Warrior (2), Undead Warrior (3), Cyclops, Orthrus, Chimera → 3");
  it.todo("scores each Sphinx, with a second Sphinx counting as a type — Sphinx, Sphinx, Chimera, Orthrus → 4");
  it.todo("scores each Sphinx beyond three types with a second Sphinx — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6");
});

